code_example:
template<typename T>
void f(T&& param); // param is a universal reference

int x = 27;
const int cx = x;

// Argument is an lvalue
f(x);  // T is deduced as int&. After reference collapsing, param's type is int&.

// Argument is a const lvalue
f(cx); // T is deduced as const int&. param's type is const int&.

// Argument is an rvalue
f(27); // T is deduced as int. param's type is int&&.
